                    if all(grid[r][c] == 0 for r in range(h))), None)

    if sep_row is not None:
        other = [row[:] for row in grid[:sep_row]]
        target = [row[:] for row in grid[sep_row + 1:]]
    elif sep_col is not None:
        other = [row[:sep_col] for row in grid]
        target = [row[sep_col + 1:] for row in grid]
    else:
        return grid

    def mode(cells):
        counts = {}
        for x in cells:
            counts[x] = counts.get(x, 0) + 1
        return max(counts, key=counts.get)

    other_bg = mode(x for row in other for x in row)
    target_mode = mode(x for row in target for x in row)

    # If the other panel's background occurs in the target, it is the
    # background there too; otherwise use the target's most common color.
    target_bg = other_bg if any(other_bg == x for row in target for x in row) else target_mode

    return [[3 if x == target_bg else other_bg for x in row] for row in target]
