    # Split the two aligned panels at their uniform separator.
    sep_row = next(
        (r for r in range(h) if len(set(grid[r])) == 1),
        None
    )
    if sep_row is not None:
        a = grid[:sep_row]
        b = grid[sep_row + 1:]
    else:
        sep_col = next(
            c for c in range(w)
            if len({grid[r][c] for r in range(h)}) == 1
        )
        a = [row[:sep_col] for row in grid]
        b = [row[sep_col + 1:] for row in grid]

    colors_a = {x for row in a for x in row}
    colors_b = {x for row in b for x in row}
    shared = colors_a & colors_b

    # The shared color marks unequal aligned cells; equal cells become 3.
    mismatch_color = next(iter(shared))
    return [
        [3 if x == y else mismatch_color for x, y in zip(row_a, row_b)]
        for row_a, row_b in zip(a, b)
    ]
